1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
3	const CURSE_SURCHARGE_RATE = 0.5;
4	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
5	const HIGH_ENCHANTMENT_THRESHOLD = 5;
6	const LOYALTY_DISCOUNT_RATE = 0.2;
7	const LOYALTY_THRESHOLD_YEARS = 2;
8	const COMPONENT_BLOCK_BASE = 60;
9	const COMPONENT_BLOCK_SIZE = 3;
10	
11	const BASE_PREMIUM: Record<string, number> = {
12	  sword: 100,
13	  amulet: 60,
14	  staff: 80,
15	  potion: 40,
16	  rune: 25,
17	  moonstone: 25,
18	};
19	
20	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
21	
22	type Item = { type: string; cursed?: boolean; enchantment?: number };
23	type Customer = { yearsWithMHPCO: number };
24	type Step = { op: "quote"; items: Item[] };
25	type Scenario = { customer: Customer; steps: Step[] };
26	
27	const countByType = (items: Item[]): Map<string, number> =>
28	  items.reduce(
29	    (counts, { type }) => counts.set(type, (counts.get(type) ?? 0) + 1),
30	    new Map<string, number>(),
31	  );
32	
33	const perItemBasePremium = (type: string): number => BASE_PREMIUM[type];
34	
35	const basePremiumForGroup = (type: string, count: number): number =>
36	  COMPONENT_TYPES.has(type) && count === COMPONENT_BLOCK_SIZE
37	    ? COMPONENT_BLOCK_BASE
38	    : count * perItemBasePremium(type);
39	
40	const basePremiumForItems = (items: Item[]): number =>
41	  [...countByType(items)].reduce(
42	    (sum, [type, count]) => sum + basePremiumForGroup(type, count),
43	    0,
44	  );
45	
46	const surchargeRateForItem = (item: Item): number =>
47	  (item.cursed ? CURSE_SURCHARGE_RATE : 0) +
48	  ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD ? HIGH_ENCHANTMENT_SURCHARGE_RATE : 0);
49	
50	const itemSurcharges = (items: Item[]): number =>
51	  items.reduce(
52	    (sum, item) => sum + perItemBasePremium(item.type) * surchargeRateForItem(item),
53	    0,
54	  );
55	
56	const roundInMHPCOsFavor = (premium: number): number => Math.ceil(premium);
57	
58	const loyaltyDiscountRate = (customer: Customer): number =>
59	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS ? LOYALTY_DISCOUNT_RATE : 0;
60	
61	const withPolicyWideModifiers = (base: number, customer: Customer): number =>
62	  base +
63	  base * FIRST_INSURANCE_SURCHARGE_RATE -
64	  base * loyaltyDiscountRate(customer);
65	
66	const quotePremium = ({ items }: Step, customer: Customer): number =>
67	  roundInMHPCOsFavor(
68	    withPolicyWideModifiers(basePremiumForItems(items), customer) + itemSurcharges(items),
69	  ) + PROCESSING_FEE;
70	
71	export const runScenario = ({ customer, steps }: Scenario): { results: Array<{ premium: number }> } => ({
72	  results: steps.map((step) => ({ premium: quotePremium(step, customer) })),
73	});
